using System.Xml;

public class InvoiceImporter
{
    // Parse an invoice XML document uploaded by a partner.
    public Invoice Parse(string xml)
    {
        var doc = new XmlDocument();
        doc.XmlResolver = new XmlUrlResolver();
        doc.LoadXml(xml);

        var total = doc.SelectSingleNode("/invoice/total")?.InnerText;
        var customer = doc.SelectSingleNode("/invoice/customer")?.InnerText;
        return new Invoice(customer, decimal.Parse(total));
    }
}

